/**
 * Response shapes for the endpoints we use. VERIFIED against live responses on
 * 2026-10-29: see docs/spotify-responses.md (generated by the in-app API Lab at /lab).
 * Spotify's docs say several fields were removed in Feb 2026 (popularity, followers,
 * available_markets), but this app still receives them. They are typed as present
 * where observed and optional where Spotify could drop them, and the UI hides
 * anything missing. Re-run the Lab to re-check.
 */

export interface SpotifyImage {
  url: string;
  width: number | null;
  height: number | null;
}

export interface SpotifyArtistRef {
  id: string;
  name: string;
  uri: string;
}

export interface SpotifyAlbumRef {
  id: string;
  name: string;
  uri: string;
  release_date?: string;
  images: SpotifyImage[];
}

export interface SpotifyTrack {
  id: string;
  name: string;
  uri: string;
  duration_ms: number;
  explicit: boolean;
  artists: SpotifyArtistRef[];
  album: SpotifyAlbumRef;
  /** 0-100 global popularity. Observed on full tracks (top, search, recent, top-tracks), not on album track lists. */
  popularity?: number;
}

/** Track as listed inside an album: no `album` field, it is implied. */
export interface SimpleTrack {
  id: string;
  name: string;
  uri: string;
  duration_ms: number;
  explicit: boolean;
  track_number: number;
  artists: SpotifyArtistRef[];
  /** Present when Spotify relinked the track to a playable version: `id` here is the ORIGINAL track id. */
  linked_from?: { id: string };
}

export interface SpotifyArtist {
  id: string;
  name: string;
  uri: string;
  images: SpotifyImage[];
  /** Observed present; often empty. Marked deprecated in the docs. */
  genres?: string[];
  /** 0-100 global popularity. Observed on full artists; optional because Spotify says it is removed. */
  popularity?: number;
  /** Observed present (`href` is always null). Optional for the same reason. */
  followers?: { total: number };
}

/** Album as returned in lists (artist albums, search). */
export interface AlbumSummary extends SpotifyAlbumRef {
  album_type?: string;
  artists: SpotifyArtistRef[];
}

/** Full album from GET /albums/{id}, including its tracks. */
export interface AlbumFull extends AlbumSummary {
  total_tracks: number;
  /** 0-100 global popularity; observed on full albums only. */
  popularity?: number;
  tracks: Paging<SimpleTrack>;
}

export interface Paging<T> {
  items: T[];
  total: number;
  limit: number;
  offset: number;
  next: string | null;
}

export interface PlayHistory {
  track: SpotifyTrack;
  played_at: string;
  context: { type: string; uri: string } | null;
}

export type TimeRange = 'short_term' | 'medium_term' | 'long_term';

export interface SearchResults {
  tracks?: Paging<SpotifyTrack>;
  artists?: Paging<SpotifyArtist>;
  albums?: Paging<AlbumSummary>;
  /** Search can return `null` entries among the playlists, so filter them out. */
  playlists?: Paging<PlaylistSummary | null>;
}

export interface StartPlaybackBody {
  uris?: string[];
  context_uri?: string;
  offset?: { uri: string } | { position: number };
  position_ms?: number;
}

/** GET /browse/new-releases (officially removed; still answers for some apps). */
export interface NewReleasesResponse {
  albums: Paging<AlbumSummary>;
}

/** GET /me. `product` is still returned ("premium" etc.), so Premium can be detected up front. */
export interface SpotifyProfile {
  id: string;
  display_name: string;
  country: string;
  product: string;
  images: SpotifyImage[];
}

/** GET /me/albums item. */
export interface SavedAlbum {
  added_at: string;
  album: AlbumSummary;
}

/** GET /me/following?type=artist (cursor paged, not the usual Paging shape). */
export interface FollowedArtistsResponse {
  artists: { items: SpotifyArtist[]; total: number; next: string | null };
}

/** GET /me/playlists item. Verified shape exposes both `tracks` and `items` counts. */
export interface PlaylistSummary {
  id: string;
  name: string;
  uri: string;
  images?: SpotifyImage[] | null;
  owner: { display_name?: string | null };
  external_urls?: { spotify?: string };
  /** Track counts: `items` is the current name, `tracks` the deprecated one. Either may be absent. */
  items?: { total?: number } | null;
  tracks?: { total?: number } | null;
}

/**
 * Podcasts and audiobooks. Spotify exposes NO popularity, follower count or play history for
 * either, so there is no real "heat" for them: pages show what the API actually returns.
 * Shapes marked (verified) come from docs/spotify-responses.md; the rest follow Spotify's docs
 * and are checked by the Lab's "Podcasts & books" group.
 */

/** A show as returned inside GET /me/shows (verified). */
export interface ShowSummary {
  id: string;
  name: string;
  uri: string;
  publisher: string;
  description: string;
  html_description: string;
  explicit: boolean;
  images: SpotifyImage[];
  languages: string[];
  media_type: string;
  total_episodes: number;
  is_externally_hosted: boolean;
  copyrights: unknown[];
  available_markets: string[];
}

/** GET /me/shows item (verified). */
export interface SavedShow {
  added_at: string;
  show: ShowSummary;
}

/** GET /me/audiobooks item: the audiobook itself, not wrapped (verified). */
export interface AudiobookSummary {
  id: string;
  name: string;
  uri: string;
  images: SpotifyImage[];
  authors: { name: string }[];
  narrators: { name: string }[];
  publisher: string;
  description: string;
  html_description: string;
  edition: string;
  explicit: boolean;
  languages: string[];
  media_type: string;
  total_chapters: number;
  is_externally_hosted: boolean;
  copyrights: unknown[];
  available_markets: string[];
}
export type SavedAudiobook = AudiobookSummary;

/** GET /shows/{id}/episodes item (documented; confirm in the Lab). */
export interface EpisodeSummary {
  id: string;
  name: string;
  uri: string;
  description: string;
  duration_ms: number;
  release_date: string;
  explicit: boolean;
  images: SpotifyImage[];
  language?: string;
  /** Only present with scope `user-read-playback-position`, which this app does not request. */
  resume_point?: { fully_played: boolean; resume_position_ms: number };
}

/** GET /audiobooks/{id}/chapters item (documented; confirm in the Lab). */
export interface ChapterSummary {
  id: string;
  name: string;
  uri: string;
  description: string;
  duration_ms: number;
  chapter_number: number;
  release_date: string;
  explicit: boolean;
  images: SpotifyImage[];
  resume_point?: { fully_played: boolean; resume_position_ms: number };
}
